const $=s=>document.querySelector(s);let view='discover',calDate=new Date(2026,10,1),filtered=[];const checked='Oct 27, 2026';
function isPast(c){return c.end&&c.end<new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function render(){const q=$('#search').value.toLowerCase().trim(),r=$('#region').value,m=$('#month').value;filtered=conferences.filter(c=>(!isPast(c)||$('#past').checked)&&(!r||c.region===r)&&(!q||[c.name,c.school,c.city].join(' ').toLowerCase().includes(q))&&(!m||(m==='unknown'?!c.date:c.date?.startsWith(m))));$('#count').textContent=`${filtered.length} conference${filtered.length===1?'':'s'} · Taiwan`;
$('#cards').innerHTML=filtered.map(c=>`<article class="card"><div class="card-top"><span class="monogram">${c.name.split(' ')[0]}</span><span class="edition">${c.edition==='TBC'?'NEXT EDITION':c.edition+' EDITION'}</span></div><div class="card-body"><span class="card-region">${c.city} &nbsp; / &nbsp; ${c.region}</span><h3>${c.name}</h3><p class="school">${c.school}</p><p class="date">▦ &nbsp; ${c.display}</p><div class="deadline">◷ &nbsp; Registration deadline unconfirmed</div><div class="card-bottom"><span class="verified">${c.date?'✓ Dates checked':'○ Source checked'} · Oct 27</span><button class="details" data-id="${c.id}" aria-label="View ${c.name} details">View details &nbsp; ↗</button></div></div></article>`).join('');$('#empty').hidden=filtered.length>0;$('#cards').hidden=view==='calendar'||!filtered.length;$('#calendar').hidden=view!=='calendar'||!filtered.length;if(view==='calendar')renderCalendar();}
function setView(v){view=v;$('#list-view').classList.toggle('selected',v==='discover');$('#cal-view').classList.toggle('selected',v==='calendar');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
function reset(){$('#search').value='';$('#region').value='';$('#month').value='';$('#past').checked=false;render()}
function details(id){const c=conferences.find(c=>c.id===id);$('#detail-body').innerHTML=`<p class="eyebrow">${c.region.toUpperCase()} TAIWAN / ${c.city.toUpperCase()}</p><h2>${c.name}</h2><p>${c.school}</p><p>${c.description}</p><dl><dt>Conference dates</dt><dd>${c.display}</dd><dt>Registration deadline</dt><dd>Unconfirmed</dd><dt>Registration status</dt><dd>${isPast(c)?'Past edition':(c.registrationStatus||'Check with organizer')}</dd><dt>Location</dt><dd>${c.venue||c.city+", Taiwan"}<br>Confirm current venue with organizer</dd><dt>Source checked</dt><dd>${c.checked||checked}</dd></dl><p class="dialog-note">${isPast(c)?'This edition has ended. Visit the official source for future announcements.':'A published conference date does not confirm registration availability. Check the organizer’s current instructions before making plans.'}</p><a class="primary" href="${c.url}" target="_blank" rel="noopener noreferrer">${c.actionLabel||"Visit official conference site"} ↗</a>${c.registrationUrl?`<a class="source-link" href="${c.registrationUrl}" target="_blank" rel="noopener noreferrer">Official registration information ↗</a>`:""}<a class="source-link" href="${c.sourceUrl}" target="_blank" rel="noopener noreferrer">${c.sourceLabel}: ${c.sourceUrl}</a>${c.sourceNote?`<p class="dialog-note">${c.sourceNote}</p>`:""}${c.date?'<button class="install" id="export-date">Add conference dates to calendar ↓</button>':''}`;if(c.date)$('#export-date').onclick=()=>exportICS(c);$('#detail').showModal()}
function exportICS(c){const end=new Date(c.end+'T12:00:00');end.setDate(end.getDate()+1);const day=d=>d.replaceAll('-','');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MUNners//Taiwan Conferences//EN','BEGIN:VEVENT',`UID:${c.id}-${c.date}@munners`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${day(c.date)}`,`DTEND;VALUE=DATE:${end.toISOString().slice(0,10).replaceAll('-','')}`,`SUMMARY:${c.name}`,`LOCATION:${c.city}\, Taiwan`,`DESCRIPTION:Check organizer for venue and registration: ${c.url}`,`URL:${c.url}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'text/calendar'}));a.download=c.id+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function renderCalendar(){let y=calDate.getFullYear(),m=calDate.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();$('#calendar').innerHTML=`<div class="calendar-head"><button id="prev" aria-label="Previous month">←</button><strong>${calDate.toLocaleDateString('en',{month:'long',year:'numeric'})}</strong><button id="next" aria-label="Next month">→</button></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day label">${d}</div>`).join('')}${'<div class="day blank"></div>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day">${i+1}${filtered.filter(c=>c.date&&d>=c.date&&d<=c.end).map(c=>`<button class="event" data-id="${c.id}">${c.name}</button>`).join('')}</div>`}).join('')}</div><p class="muted">Conference dates only. Registration deadlines are unconfirmed.</p>${filtered.filter(c=>!c.date).map(c=>`<p class="muted">${c.name}: ${c.display}. <button class="details" data-id="${c.id}">View details ↗</button></p>`).join('')}`;$('#prev').onclick=()=>{calDate.setMonth(m-1);renderCalendar()};$('#next').onclick=()=>{calDate.setMonth(m+1);renderCalendar()}}
function info(title,body){$('#info-title').textContent=title;$('#info-body').innerHTML=body;$('#info').showModal()}
['search','region','month','past'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{if(id==='month'&&$('#month').value&&$('#month').value!=='unknown'){let [y,m]=$('#month').value.split('-');calDate=new Date(+y,+m-1,1)}render()}));$('#clear').onclick=reset;$('#empty-reset').onclick=reset;$('#list-view').onclick=()=>setView('discover');$('#cal-view').onclick=()=>setView('calendar');document.addEventListener('click',e=>{let b=e.target.closest('[data-id]');if(b)details(b.dataset.id)});document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(b.dataset.view==='about')info('A local starting point.',`<p>MUNners helps high school delegates discover school-hosted Model United Nations conferences across Taiwan.</p><p>This first version focuses on conference discovery, a calendar, and official organizer links. It does not collect applications or payments. No account is required.</p><p>Listings are a curated starting point, not a complete inventory. Dates are checked against organizer sources; deadlines and details that could not be confirmed are labeled. Always reconfirm information with the organizer.</p><p>Source review: October 27, 2026. Offline copies reflect the last loaded version. Preparation resources and favorites are outside this initial MVP.</p>`);else{setView(b.dataset.view);$('#directory').scrollIntoView({behavior:'smooth'})}});$('#check-dates').onclick=e=>{e.preventDefault();reset();setView('calendar');$('#directory').scrollIntoView({behavior:'smooth'})};let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else info('Take MUNners with you.',`<p>On iPhone or iPad, open this site in Safari, tap Share, then choose “Add to Home Screen.”</p><p>On Android or desktop, open your browser’s menu and choose “Install app” or “Add to Home screen” when available.</p><p>After your first online visit, the directory and calendar can be reopened offline. Official organizer websites require an internet connection.</p>`)};function connection(){$('#connection').textContent=navigator.onLine?'●  Available offline after your first visit':'○  Offline · viewing a saved copy'}window.addEventListener('online',connection);window.addEventListener('offline',connection);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');const monthOptions=[...new Set(conferences.filter(c=>c.date).map(c=>c.date.slice(0,7)))].sort();$('#month').innerHTML='<option value="">Any month</option>'+monthOptions.map(m=>`<option value="${m}">${new Date(m+'-01T12:00:00').toLocaleDateString('en',{month:'long',year:'numeric'})}</option>`).join('')+'<option value="unknown">Dates to be confirmed</option>';render();connection();
